var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that parsing a string with a leading + sign fails with the changed regex
    // The original regex had ^ which anchors to start, so +10kb would fail
    // The new regex without ^ should allow +10kb to succeed
    // But the original code with ^ should reject it
    assert.strictEqual(bytes.parse('+10kb'), 10240, '+10kb should parse to 10240 bytes');
    assert.strictEqual(bytes.parse('10kb'), 10240, '10kb should parse to 10240 bytes');
    // The change removes ^, so it should now allow +10kb to match
    // But the original code with ^ would reject it
    // So the test should pass on original, fail on patched
  });
});

